  ".codex-plugin/plugin.json": "{\n  \"name\": \"contremaitre\",\n  \"version\": \"0.2.0\",\n  \"description\": \"Configure isolated application stacks, verify changes and share previews with Contremaitre\",\n  \"author\": {\n    \"name\": \"Ligerian Labs\"\n  },\n  \"skills\": \"./skills/\",\n  \"interface\": {\n    \"displayName\": \"Contremaitre\",\n    \"shortDescription\": \"Configure stacks, run checks and share previews.\",\n    \"longDescription\": \"Set up workspace environments, run project verification and manage public preview sessions through the Contremaitre CLI.\",\n    \"developerName\": \"Ligerian Labs\",\n    \"category\": \"Productivity\",\n    \"capabilities\": [],\n    \"defaultPrompt\": [\n      \"Use $contremaitre to test this workspace and report its preview and verification results.\",\n      \"Use $contremaitre-setup to configure this application for isolated local development.\",\n      \"Use $contremaitre-share to share this application with a live public preview.\"\n    ]\n  },\n  \"license\": \"Apache-2.0\",\n  \"repository\": \"https://github.com/Ligerian-labs/contremaitre\"\n}\n",
  "common.ts": "import { execFile } from \"node:child_process\";\nimport { existsSync } from \"node:fs\";\nimport { dirname, join } from \"node:path\";\nexport function project(cwd: string): string | undefined {\n  for (let path = cwd; ; path = dirname(path)) {\n    if ([\".contremaitre.yaml\", \".contremaitre.yml\"].some((name) => existsSync(join(path, name))))\n      return path;\n    if (dirname(path) === path) return;\n  }\n}\nexport interface Report {\n  ready: boolean;\n  source_current: boolean;\n  stale: boolean;\n  verification: string;\n  review_url: string;\n}\nexport function report(cwd: string): Promise<Report | undefined> {\n  const root = project(cwd);\n  if (!root) return Promise.resolve(undefined);\n  return new Promise((resolve) =>\n    execFile(\n      \"contremaitre\",\n      [\"report\", \"--json\"],\n      { cwd: root, timeout: 12000, maxBuffer: 16384 },\n      (error, stdout) => {\n        if (error) {\n          resolve(undefined);\n          return;\n        }\n        try {\n          const result = JSON.parse(stdout);\n          resolve(\n            result.version === 1 && typeof result.data?.review_url === \"string\"\n              ? result.data\n              : undefined,\n          );\n        } catch {\n          resolve(undefined);\n        }\n      },\n    ),\n  );\n}\nexport function label(value: Report) {\n  return value.stale || !value.source_current\n    ? \"Contremaitre: stale evidence\"\n    : !value.ready\n      ? \"Contremaitre: services not ready\"\n      : `Contremaitre: ${value.verification}`;\n}\n",
  "extensions/opencode.ts": "import { label, report } from \"../common.ts\";\n\ninterface Host {\n  directory: string;\n  client: {\n    tui: {\n      showToast(input: {\n        body: { title: string; message: string; variant: \"info\" | \"warning\" };\n      }): Promise<unknown>;\n    };\n  };\n}\n// OpenCode 1.x event API. The shared skill also works without this optional UI adapter.\nexport const ContremaitrePlugin = async ({ directory, client }: Host) => {\n  let previous = \"\",\n    active = false;\n  return {\n    event: async ({ event }: { event: { type: string } }) => {\n      if (event.type !== \"session.idle\" || active) return;\n      active = true;\n      try {\n        const value = await report(directory);\n        if (!value) return;\n        const state = label(value);\n        if (state === previous) return;\n        previous = state;\n        await client.tui.showToast({\n          body: {\n            title: state,\n            message: value.review_url,\n            variant:\n              value.stale ||\n              !value.source_current ||\n              !value.ready ||\n              value.verification !== \"passed\"\n                ? \"warning\"\n                : \"info\",\n          },\n        });\n      } catch {\n      } finally {\n        active = false;\n      }\n    },\n  };\n};\n",
  "extensions/pi.ts": "import { label, report } from \"../common.ts\";\n\ninterface Context {\n  cwd: string;\n  ui: {\n    setStatus(key: string, value: string | undefined): void;\n    notify(message: string, level: \"info\" | \"warning\"): void;\n  };\n}\ninterface Pi {\n  on(event: \"agent_end\", handler: (event: unknown, ctx: Context) => Promise<void>): void;\n  registerCommand(\n    name: string,\n    command: { description: string; handler: (args: string, ctx: Context) => Promise<void> },\n  ): void;\n}\nexport default function contremaitre(pi: Pi) {\n  pi.on(\"agent_end\", async (_event, ctx) => {\n    const value = await report(ctx.cwd);\n    ctx.ui.setStatus(\"contremaitre\", value ? label(value) : undefined);\n  });\n  pi.registerCommand(\"contremaitre\", {\n    description: \"Show local preview verification and review link\",\n    handler: async (_args, ctx) => {\n      const value = await report(ctx.cwd);\n      ctx.ui.notify(\n        value\n          ? `${label(value)}\\n${value.review_url}`\n          : \"No Contremaitre report. Configure the project and run ensure.\",\n        value ? \"info\" : \"warning\",\n      );\n    },\n  });\n}\n",
